import { canonicalSha256 } from '../core/canonical-json.mjs';
import { matchesAny } from './glob.mjs';
export function compileScope({change,policy={}}){const include=policy.include?.length?policy.include:['**'];const exclude=policy.exclude??[];const included=[];const excluded=[];for(const item of [...(change?.files??[])].sort((a,b)=>a.path.localeCompare(b.path))){if(matchesAny(item.path,exclude)){excluded.push({...item,reason:'excluded-by-policy'});continue;}if(!matchesAny(item.path,include)){excluded.push({...item,reason:'not-in-include-policy'});continue;}included.push({...item,reason:'included-by-policy'});}const subject={schemaVersion:1,included,excluded,policy:{include:[...include],exclude:[...exclude]}};return Object.freeze({...subject,scopeSha256:canonicalSha256(subject)});}
